package io.nagode.service;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import java.util.*;
@Service public class OwnershipService {private final JdbcTemplate db;public OwnershipService(JdbcTemplate db){this.db=db;}public boolean ownsPayment(UUID user,UUID payment){Integer n=db.queryForObject("select count(*) from payments p join accounts a on a.id=p.payer_account where p.id=? and a.owner_type='USER' and a.owner_id=?",Integer.class,payment,user.toString());return n!=null&&n==1;}public List<Map<String,Object>> payments(UUID user,int limit,int offset){return db.queryForList("select p.id,p.amount,p.currency,p.status,p.psp_reference,p.created_at,p.updated_at from payments p join accounts a on a.id=p.payer_account where a.owner_type='USER' and a.owner_id=? order by p.created_at desc limit ? offset ?",user.toString(),limit,offset);}}
